function loadState(){try{const s=JSON.parse(localStorage.getItem('aventuraPesqueraSave'));if(s&&typeof s==='object'){const merged={...defaultState(),...s,unlocked:s.unlocked||[0],hold:s.hold||[],discovered:s.discovered||[],skillNodes:s.skillNodes||[],treasures:s.treasures||[],relics:s.relics||[],equippedRelics:s.equippedRelics||[],relicStorageLevel:Math.max(1,Math.min(5,Number(s.relicStorageLevel)||1)),aquarium:s.aquarium||[],aquariumUpgrades:Array.isArray(s.aquariumUpgrades)?s.aquariumUpgrades:[],completedMissions:s.completedMissions||[]};merged.aquariumLevel=Math.max(1,Math.min(10,Math.floor(Number(s.aquariumLevel)||Math.min(10,Math.max(1,merged.aquarium.length||1)))));if(!Array.isArray(s.aquariumUpgrades)&&Number(s.aquariumLevel)>1)merged.aquariumUpgrades=Array.from({length:Math.min(30,(Math.min(10,Math.floor(Number(s.aquariumLevel))-1))*3)},(_,i)=>i);merged.aquariumUpgrades=[...new Set(merged.aquariumUpgrades.filter(id=>Number.isInteger(id)&&id>=0&&id<30))].sort((a,b)=>a-b);merged.aquarium=[...new Set(merged.aquarium.map(Number).filter(id=>Number.isInteger(id)&&id>=0&&id<fish.length))].slice(0,aquariumCapacityFor(merged.aquariumUpgrades));return merged}}catch(e){}return defaultState()}
function save(){try{localStorage.setItem('aventuraPesqueraSave',JSON.stringify(state))}catch(e){}}
function exportSave(){try{const payload={app:'Aventura Pesquera',version:1,exportedAt:new Date().toISOString(),save:state};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`aventura-pesquera-partida-${new Date().toISOString().slice(0,10)}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Partida exportada correctamente')}catch(e){modal({icon:'⚠️',title:'No se pudo exportar',desc:'Tu navegador no ha podido crear el archivo de la partida.',action:'Entendido'})}}
function importSaveFile(file){if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(String(reader.result||''));const candidate=parsed&&parsed.save?parsed.save:parsed;if(!candidate||typeof candidate!=='object'||Array.isArray(candidate)||!Array.isArray(candidate.hold)||!Array.isArray(candidate.discovered)||!Array.isArray(candidate.unlocked)||!Array.isArray(candidate.skillNodes)||!Number.isFinite(Number(candidate.money))||!Number.isFinite(Number(candidate.day)))throw new Error('invalid save');const clean={...defaultState(),...candidate};clean.money=Math.max(0,Number(clean.money)||0);clean.day=Math.max(1,Math.floor(Number(clean.day)||1));clean.zone=Math.max(0,Math.min(zones.length-1,Math.floor(Number(clean.zone)||0)));clean.unlocked=[...new Set(clean.unlocked.map(Number).filter(n=>Number.isInteger(n)&&n>=0&&n<zones.length))];if(!clean.unlocked.includes(0))clean.unlocked.unshift(0);if(!clean.unlocked.includes(clean.zone))clean.zone=0;clean.treasures=Array.isArray(clean.treasures)?clean.treasures.filter(t=>t&&typeof t.name==='string'&&Number.isFinite(Number(t.value))).map(t=>({...t,value:Math.max(0,Number(t.value)||0)})):[];clean.aquarium=Array.isArray(clean.aquarium)?[...new Set(clean.aquarium.map(Number).filter(id=>Number.isInteger(id)&&id>=0&&id<fish.length))].slice(0,10):[];clean.aquariumLevel=Math.max(1,Math.min(10,Math.floor(Number(candidate.aquariumLevel)||Math.min(10,Math.max(1,clean.aquarium.length||1)))));clean.aquariumUpgrades=Array.isArray(candidate.aquariumUpgrades)?[...new Set(clean.aquariumUpgrades.filter(id=>Number.isInteger(id)&&id>=0&&id<30))].sort((a,b)=>a-b):Array.from({length:Math.min(30,Math.max(0,Math.min(10,Math.floor(Number(candidate.aquariumLevel)||1)-1)*3))},(_,i)=>i);clean.aquarium=clean.aquarium.slice(0,aquariumCapacityFor(clean.aquariumUpgrades));clean.completedMissions=Array.isArray(clean.completedMissions)?clean.completedMissions.filter(id=>['catch10','rare5','treasure3','travel3'].includes(id)):[];clean.boatSkin=Math.max(0,Math.min(4,Math.floor(Number(clean.boatSkin)||0)));clean.tournamentClaimed=Boolean(clean.tournamentClaimed);clean.hold=clean.hold.map(Number).filter(id=>Number.isInteger(id)&&id>=0&&id<fish.length);clean.discovered=[...new Set(clean.discovered.map(Number).filter(id=>Number.isInteger(id)&&id>=0&&id<fish.length))];clean.skillNodes=[...new Set(clean.skillNodes.filter(id=>typeof id==='string'&&SKILLS.some(skill=>skill.id===id)))];clean.sound=Boolean(clean.sound);clean.musicVolume=Math.max(0,Math.min(100,Number(clean.musicVolume)||0));clean.effectsVolume=Math.max(0,Math.min(100,Number(clean.effectsVolume)||0));clean.hasStarted=Boolean(clean.hasStarted);clean.totalCaught=Math.max(0,Number(clean.totalCaught)||0);clean.totalSales=Math.max(0,Number(clean.totalSales)||0);state=clean;save();updateTop();renderMenu();renderZones();renderUpgrades();renderBook();renderHold();renderSettings();syncMusicVolume();toast('Partida importada correctamente');showScreen(state.hasStarted?'menu':'intro')}catch(e){modal({icon:'⚠️',title:'Archivo no válido',desc:'El archivo no parece una partida válida de Aventura Pesquera. No se ha cambiado tu progreso.',action:'Entendido'})}};reader.onerror=()=>modal({icon:'⚠️',title:'Error al leer el archivo',desc:'No se ha podido leer el archivo seleccionado.',action:'Entendido'});reader.readAsText(file)}
async function clearAppCache(){try{if('caches'in window){const keys=await caches.keys();await Promise.all(keys.filter(key=>key.startsWith('aventura-pesquera')).map(key=>caches.delete(key)))}}catch(e){}try{if('serviceWorker'in navigator){const registrations=await navigator.serviceWorker.getRegistrations();await Promise.all(registrations.map(registration=>registration.unregister()))}}catch(e){}try{if(location.protocol==='https:'||location.protocol==='http:'){const url=new URL(location.href);url.searchParams.set('refresh',String(Date.now()));location.replace(url.href)}else location.reload()}catch(e){try{location.reload()}catch(_){}}}
function cash(n){return Math.round(n).toLocaleString('es-ES')+' €'}
function hasSkill(id){return (state.skillNodes||[]).includes(id)}
function skillCount(branch){return SKILLS.filter(n=>n.branch===branch&&hasSkill(n.id)).length}
function capacity(){return 5+SKILLS.filter(n=>n.branch==='storage'&&n.effect==='capacity'&&hasSkill(n.id)).reduce((a,n)=>a+n.amount,0)}
function rodRange(){return 105+(state.rod-1)*42+skillCount('rod')*18}
function boatSpeed(){const bonus=SKILLS.filter(n=>n.branch==='boat'&&n.effect==='speed'&&hasSkill(n.id)).reduce((a,n)=>a+n.amount,0);return (.28+(state.boat-1)*.1)*(1+bonus+relicBonus('speed'))}
function fishValueMultiplier(f){let mult=1+SKILLS.filter(n=>n.branch==='storage'&&n.effect==='premium'&&hasSkill(n.id)).reduce((a,n)=>a+n.amount,0);if(f&&f.rarity>=2)mult+=SKILLS.filter(n=>n.branch==='storage'&&n.effect==='rarevalue'&&hasSkill(n.id)).reduce((a,n)=>a+n.amount,0);return mult}
function currentZone(){return zones[state.zone]}
function discoveredSet(){return new Set(state.discovered)}
function price(f){return Math.max(1,Math.round(f.value*(1+(state.rod-1)*.025)*fishValueMultiplier(f)*(1+relicBonus('sale'))))}
function syncMusicVolume(){if(music)music.volume=Math.max(0,Math.min(1,(Number(state.musicVolume)||0)/100))}
function startMusic(){if(!music)return;syncMusicVolume();try{const attempt=music.play();if(attempt&&typeof attempt.catch==='function')attempt.catch(()=>{})}catch(e){}}
function sound(type='click'){if(!state.sound||Number(state.effectsVolume)<=0)return;try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const seq=type==='catch'?[520,680,850]:type==='sell'?[560,780]:type==='cast'?[300,470]:type==='upgrade'?[430,620,790]:[430];seq.forEach((hz,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type==='cast'?'triangle':'sine';o.frequency.value=hz;const volume=.035*(Math.max(0,Math.min(100,Number(state.effectsVolume)||0))/100);g.gain.setValueAtTime(volume,audioCtx.currentTime+i*.09);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+i*.09+.12);o.connect(g);g.connect(audioCtx.destination);o.start(audioCtx.currentTime+i*.09);o.stop(audioCtx.currentTime+i*.09+.13)})}catch(e){}}
function showScreen(name){if(sessionActive&&name!=='fishing'&&name!=='settings')return;activeScreen=name;screens.forEach(s=>$(s).classList.toggle('hidden',s!==name));window.scrollTo({top:0,behavior:'smooth'});if(name==='menu')renderMenu();if(name==='zones')renderZones();if(name==='upgrades')renderUpgrades();if(name==='encyclopedia')renderBook();if(name==='hold')renderHold();if(name==='settings')renderSettings();if(name==='boat')renderBoat();if(name==='treasures')renderTreasures();if(name==='aquarium')renderAquarium();if(name==='missions')renderMissions();save()}
function openSettings(){if(activeScreen==='fishing'&&sessionActive){sessionActive=false;expeditionPausedForSettings=true;keys.left=false;keys.right=false;lastFrame=0}sound('click');showScreen('settings')}
function returnFromSettings(){if(expeditionPausedForSettings){expeditionPausedForSettings=false;showScreen('fishing');sessionActive=true;lastFrame=0;startLoop();return}showScreen('menu')}
function updateTop(){ $('money').textContent=cash(state.money);$('day').textContent='Día '+state.day;$('menu-day').textContent=state.day;$('encyclopedia-progress').textContent=state.discovered.length.toLocaleString('es-ES')+' / 1.200 descubiertos';$('hold-summary').textContent=state.hold.length+' peces almacenados';updateExpeditionHoldCounter()}
function updateExpeditionHoldCounter(){const count=state.hold.length,cap=capacity();if($('expedition-hold-count'))$('expedition-hold-count').textContent=`${count} / ${cap}`;if($('expedition-hold-capacity'))$('expedition-hold-capacity').textContent=`${count} / ${cap}`;if($('expedition-hold-free'))$('expedition-hold-free').textContent=String(Math.max(0,cap-count))}
function renderMenu(){updateTop();$('current-zone-title').textContent=currentZone().name;$('current-zone-desc').textContent=currentZone().desc}
function renderZones(){ $('zone-grid').innerHTML=zones.map((z,i)=>{let unlocked=state.unlocked.includes(i),current=i===state.zone;return `<button class="zone-card ${current?'current':''}" data-zone="${i}" ${!unlocked&&state.money<z.price?'disabled':''}><span class="zone-art" style="background:linear-gradient(145deg,${z.color[0]},${z.color[1]})">${z.emoji}</span><span class="zone-info"><b>${z.name}</b><p>${z.desc}</p><small>◉ ${z.depth} · ${z.pool.length} especies base</small></span><span class="zone-price">${current?'ACTUAL':unlocked?'DESBLOQUEADA':cash(z.price)}</span>${!unlocked?'<span class="zone-lock">🔒</span>':''}</button>`}).join('')}
