function upgradeAquarium(id){const next=AQUARIUM_SKILLS.find(n=>!aquariumOwned(n.id));const skill=id===undefined?next:AQUARIUM_SKILLS[id];if(!skill||aquariumOwned(skill.id)||next?.id!==skill.id)return;if(!state.unlocked.includes(skill.zoneGate)){toast(`Desbloquea primero ${zones[skill.zoneGate].name} para esta mejora`);return}if(state.money<skill.cost){toast(`Necesitas ${cash(skill.cost)} para esta mejora`);return}state.money-=skill.cost;state.aquariumUpgrades.push(skill.id);state.aquariumUpgrades.sort((a,b)=>a-b);state.aquariumLevel=aquariumCapacity();save();updateTop();renderAquarium();renderUpgrades();sound('upgrade');toast(`Mejora desbloqueada: ${skill.name}`)}
function renderAquarium(){const query=($('aquarium-search')?.value||'').trim().toLocaleLowerCase('es'),allDiscovered=state.discovered.filter(id=>fish[id]&&fish[id].name.toLocaleLowerCase('es').includes(query)),shown=state.aquarium||[],cap=aquariumCapacity(),income=aquariumDailyIncome();$('aquarium-count').textContent=shown.length;$('aquarium-income').textContent=cash(income);$('aquarium-summary').textContent=`${shown.length}/${cap} peces · +${Math.round(aquariumPriceBonus()*100)}% ingresos`;$('aquarium-capacity').textContent=`${shown.length} / ${cap}`;$('aquarium-income-total').textContent=cash(income)+' / día';$('aquarium-tank').innerHTML=shown.length?shown.map((id,i)=>{const f=fish[id];return `<button type="button" class="tank-fish tank-fish-${i%5}" data-aquarium-info="${id}" title="Ver información de ${f.name}" style="--fish-delay:${i*-1.7}s">${f.emoji}</button>`}).join(''):'<div class="tank-empty"><span>🐠</span><b>Tu pecera está vacía</b><span>Elige un pez descubierto de la colección de abajo.</span></div>';$('aquarium-list').innerHTML=allDiscovered.length?allDiscovered.slice(0,120).map(id=>{const f=fish[id],isShown=shown.includes(id),full=!isShown&&shown.length>=cap,qualityLocked=!aquariumRarityUnlocked(f.rarity);return `<article class="feature-card aquarium-choice ${isShown?'feature-active':''} ${qualityLocked?'quality-locked':''}"><div class="feature-emoji">${qualityLocked?'🔒':f.emoji}</div><h3>${f.name}</h3><p>${rarities[f.rarity]} · ${f.weight} kg</p><strong>${qualityLocked?'Requiere mejora de museo':'Genera '+cash(aquariumFishIncome(id))+' / día'}</strong>${qualityLocked?`<small>Desbloquea la mejora de calidad para exponer esta rareza.</small>`:`<button class="${isShown?'secondary':'primary'}" data-aquarium="${id}" ${isShown||full?'disabled':''}>${isShown?'En la pecera':full?'Mejora la capacidad':'Añadir a la pecera'}</button>`}</article>`}).join(''):'<div class="empty-state">🐠 Descubre peces en tus expediciones para añadirlos al acuario.</div>'}
function renderMissions(){const completed=new Set(state.completedMissions||[]);$('mission-list').innerHTML=missionDefs.map(m=>{const n=Math.min(m.goal,m.progress()),done=completed.has(m.id),ready=n>=m.goal&&!done;return `<article class="feature-card"><div class="feature-emoji">${done?'✅':'📜'}</div><h3>${m.title}</h3><p>${m.desc}</p><div class="mission-progress"><span style="width:${n/m.goal*100}%"></span></div><small>${done?'Completada':n+' / '+m.goal} · Recompensa ${cash(m.reward)}</small><button class="${ready?'primary':'secondary'}" data-mission="${m.id}" ${!ready?'disabled':''}>${done?'Completada':ready?'Cobrar recompensa':'En progreso'}</button></article>`}).join('');$('tournament-score').textContent=String(state.totalCaught);$('tournament-prize').textContent=cash(500+Math.min(5000,state.totalCaught*20));$('claim-tournament').disabled=state.totalCaught<25||state.tournamentClaimed;$('claim-tournament').textContent=state.tournamentClaimed?'Premio reclamado':state.totalCaught<25?'Necesitas 25 capturas':'¡Reclamar premio';}
