$('boat-options').addEventListener('click',e=>{const b=e.target.closest('[data-boat]');if(b)buyBoat(Number(b.dataset.boat))});$('treasure-list').addEventListener('click',e=>{const eq=e.target.closest('[data-equip-relic]');if(eq){const id=eq.dataset.equipRelic;if(state.equippedRelics.length>=Math.min(boatRelicSlots(),relicCapacity())){toast('No tienes espacios de reliquia disponibles');return}if(!state.equippedRelics.includes(id))state.equippedRelics.push(id);save();renderTreasures();sound('upgrade');return}const sell=e.target.closest('[data-sell-relic]');if(sell){const id=sell.dataset.sellRelic,r=state.relics.find(x=>x.id===id);if(!r)return;state.relics=state.relics.filter(x=>x.id!==id);state.equippedRelics=state.equippedRelics.filter(x=>x!==id);state.money+=r.value;state.totalSales+=r.value;save();updateTop();renderTreasures();sound('sell');return}});$('sell-treasures').addEventListener('click',()=>{if(!state.treasures.length)return;const total=state.treasures.reduce((n,t)=>n+t.value,0),count=state.treasures.length;state.treasures=[];state.money+=total;state.totalSales+=total;save();updateTop();renderTreasures();sound('sell');modal({icon:'💰',title:'Reliquias vendidas',desc:`Has vendido ${count} reliquias recuperadas por ${cash(total)}.`,stats:[['Ingresos',cash(total)]],action:'Continuar'})});$('aquarium-list').addEventListener('click',e=>{const b=e.target.closest('[data-aquarium]');if(!b)return;const id=Number(b.dataset.aquarium);if(!state.discovered.includes(id)||!fish[id]||!aquariumRarityUnlocked(fish[id].rarity)||state.aquarium.includes(id)||state.aquarium.length>=aquariumCapacity())return;state.aquarium.push(id);save();renderAquarium();toast(`${fish[id].name} añadido a la pecera`)});$('aquarium-tank').addEventListener('click',e=>{const b=e.target.closest('[data-aquarium-info]');if(!b)return;const id=Number(b.dataset.aquariumInfo),f=fish[id];if(!f)return;modal({icon:f.emoji,title:f.name,eyebrow:rarities[f.rarity],desc:'Información del ejemplar expuesto en tu acuario.',stats:[['Rareza',rarities[f.rarity]],['Peso',f.weight+' kg'],['Valor de venta',cash(f.value)],['Ingresos diarios',cash(aquariumFishIncome(id))]],action:'Retirar del acuario',onAction:()=>{hideModal();state.aquarium=state.aquarium.filter(x=>x!==id);save();renderAquarium();toast(`${f.name} retirado de la pecera`)}})});$('aquarium-search').addEventListener('input',renderAquarium);$('mission-list').addEventListener('click',e=>{const b=e.target.closest('[data-mission]');if(b)claimMission(b.dataset.mission)});$('claim-tournament').addEventListener('click',()=>{if(state.totalCaught<25||state.tournamentClaimed)return;const reward=500+Math.min(5000,state.totalCaught*20);state.money+=reward;state.tournamentClaimed=true;save();updateTop();renderMissions();sound('upgrade');modal({icon:'🏆',title:'¡Torneo completado!',desc:`Has ganado el torneo con ${state.totalCaught} capturas.`,stats:[['Premio',cash(reward)]],action:'¡Genial!'})});
// Navigation and buttons
$('begin').addEventListener('click',()=>{startMusic();state.hasStarted=true;save();sound('click');showScreen('menu')});$('brand-home').addEventListener('click',e=>{e.preventDefault();if(expeditionPausedForSettings){returnFromSettings();return}if(!sessionActive)showScreen(state.hasStarted?'menu':'intro')});$('settings-open').addEventListener('click',openSettings);$('leave-expedition').addEventListener('click',()=>{if(sessionActive)endFishing()});$('open-expedition-hold').addEventListener('click',openExpeditionHold);$('close-expedition-hold').addEventListener('click',closeExpeditionHold);$('go-fishing').addEventListener('click',startFishing);document.querySelectorAll('[data-screen]').forEach(b=>b.addEventListener('click',()=>{sound('click');showScreen(b.dataset.screen)}));document.querySelectorAll('[data-back]').forEach(b=>b.addEventListener('click',()=>{sound('click');if(activeScreen==='settings')returnFromSettings();else showScreen('menu')}));$('zone-grid').addEventListener('click',e=>{const b=e.target.closest('[data-zone]');if(b){selectZone(Number(b.dataset.zone));renderZones()}});$('upgrade-grid').addEventListener('click',e=>{const rs=e.target.closest('[data-relic-storage-upgrade]');if(rs){const idx=Number(rs.dataset.relicStorageUpgrade),expected=(relicCapacity()-1)*3,cost=Math.round(900*Math.pow(1.75,idx));if(idx!==expected||state.money<cost)return;state.money-=cost;state.relicStorageLevel=Math.min(5,state.relicStorageLevel+1);save();updateTop();renderUpgrades();renderTreasures();sound('upgrade');return}const aq=e.target.closest('[data-aquarium-upgrade]');if(aq){upgradeAquarium(Number(aq.dataset.aquariumUpgrade));renderUpgrades();return}const tab=e.target.closest('[data-branch]');if(tab){selectedSkillBranch=tab.dataset.branch;renderUpgrades();sound('click');return}const b=e.target.closest('[data-skill]');if(b)openSkillDetail(b.dataset.skill)});$('hold-list').addEventListener('click',e=>{const b=e.target.closest('[data-sell]');if(b)sellIndex(Number(b.dataset.sell))});$('sell-all').addEventListener('click',sellAll);$('fish-search').addEventListener('input',()=>{bookPage=0;renderBook()});$('rarity-filter').addEventListener('change',()=>{bookPage=0;renderBook()});$('prev-page').addEventListener('click',()=>{bookPage--;renderBook()});$('next-page').addEventListener('click',()=>{bookPage++;renderBook()});$('cast-button').addEventListener('click',castLine);$('left-touch').addEventListener('pointerdown',e=>{e.preventDefault();keys.left=true});$('right-touch').addEventListener('pointerdown',e=>{e.preventDefault();keys.right=true});['pointerup','pointerleave','pointercancel'].forEach(ev=>{$('left-touch').addEventListener(ev,()=>{keys.left=false});$('right-touch').addEventListener(ev,()=>{keys.right=false})});document.addEventListener('keydown',e=>{if(!sessionActive)return;if(['a','A','d','D','e','E','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(e.key.toLowerCase()==='a'||e.key==='ArrowLeft')keys.left=true;if(e.key.toLowerCase()==='d'||e.key==='ArrowRight')keys.right=true;if(e.key.toLowerCase()==='e'||e.key===' ')castLine()});document.addEventListener('keyup',e=>{if(e.key.toLowerCase()==='a'||e.key==='ArrowLeft')keys.left=false;if(e.key.toLowerCase()==='d'||e.key==='ArrowRight')keys.right=false});$('sound-toggle').addEventListener('click',()=>{state.sound=!state.sound;save();renderSettings();if(state.sound)sound('click')});$('music-volume').addEventListener('input',e=>{state.musicVolume=Number(e.target.value);$('music-volume-value').textContent=state.musicVolume+' %';syncMusicVolume();save();if(music.paused&&state.musicVolume>0)startMusic()});$('effects-volume').addEventListener('input',e=>{state.effectsVolume=Number(e.target.value);$('effects-volume-value').textContent=state.effectsVolume+' %';save()});$('fullscreen').addEventListener('click',async()=>{try{if(!document.fullscreenElement)await $('app').requestFullscreen();else await document.exitFullscreen();$('fullscreen').textContent=document.fullscreenElement?'⛶ Salir de pantalla completa':'⛶ Activar'}catch(e){modal({icon:'⛶',title:'Pantalla completa no disponible',desc:'Tu navegador no permite pantalla completa en este contexto. Prueba a abrir la aplicación desde una pestaña normal.',action:'Entendido'})}});document.addEventListener('fullscreenchange',()=>$('fullscreen').textContent=document.fullscreenElement?'⛶ Salir de pantalla completa':'⛶ Activar');$('install-app').addEventListener('click',async()=>{if(!installPrompt)return;installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;renderSettings()});$('export-save').addEventListener('click',exportSave);$('import-save').addEventListener('click',()=>$('import-save-file').click());$('import-save-file').addEventListener('change',e=>{const file=e.target.files&&e.target.files[0];if(file)modal({icon:'📥',eyebrow:'IMPORTAR PARTIDA',title:'¿Sustituir tu progreso?',desc:'Se reemplazará la partida actual por el contenido del archivo seleccionado.',stats:[],action:'Importar partida',onAction:()=>{hideModal();importSaveFile(file);e.target.value=''}})});$('reset-game').addEventListener('click',()=>modal({icon:'⚠️',eyebrow:'BORRAR PROGRESO',title:'¿Reiniciar la partida?',desc:'Se perderán el dinero, las mejoras, las zonas desbloqueadas y todas las especies descubiertas. Esta acción no se puede deshacer.',stats:[],action:'Sí, reiniciar',onAction:async()=>{state=defaultState();expeditionPausedForSettings=false;expeditionPausedForHold=false;sessionActive=false;save();hideModal();showScreen('intro');updateTop();sound('click');toast('Partida reiniciada. Limpiando caché…');await clearAppCache()}}));$('modal-close').addEventListener('click',hideModal);$('modal').addEventListener('click',e=>{if(e.target===$('modal'))hideModal()});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;renderSettings()});window.addEventListener('appinstalled',()=>{installPrompt=null;renderSettings()});
